{
  "name": "parties.search-parties",
  "kind": "read",
  "description": "Search visible display names in the envelope tenant using trimmed, case-insensitive, diacritic-normalized exact, prefix, contains and fuzzy matching. Type and Active apply before paging; totals exclude erased parties. Empty query returns no matches. Date filters and advanced search modes reject. Use envelope paging: default size 20 and offset 0, maximum size 100, page-aligned offsets or a scoped continuation cursor. To continue, supply the returned paging.nextCursor without offset, keeping the same query, filters, envelope tenant, user and page size.",
  "schema": {
    "type": [
      "object",
      "null"
    ],
    "properties": {
      "Query": {
        "type": "string",
        "description": "Display-name query, at most 512 UTF-16 units including whitespace before trimming. Oversized input rejects; empty or whitespace returns no matches. Contact channels and business identifiers are not searched."
      },
      "Type": {
        "enum": [
          "Unknown",
          "Person",
          "Organization",
          null
        ],
        "description": "Optional party kind: Person or Organization; Unknown and other values reject. Applied before paging."
      },
      "Active": {
        "type": [
          "boolean",
          "null"
        ],
        "description": "Optional active-status filter, applied before paging; omitted includes active and inactive parties."
      }
    },
    "required": [
      "Query"
    ],
    "additionalProperties": false
  },
  "example": {
    "Query": "Ada",
    "Type": "Person",
    "Active": true
  },
  "envelope": {
    "aggregateIdRequired": false,
    "idempotencyKeyRequired": false,
    "arguments": [
      "tenant",
      "aggregateId",
      "entityId",
      "pageSize",
      "offset",
      "cursor"
    ]
  },
  "lintFindings": [],
  "submittable": false,
  "reason": "configuration_invalid"
}
